//! 🎛️ One resident default producer lends the actual cursor and output slots.
use super::*;
use crate::native_decoding::{OriginalEffectProducer,OriginalEffectReply,OriginalEffectReplyComplete};
pub(super) struct Producer<T:NativeDefault>(std::marker::PhantomData<fn()->T>);
impl<T:NativeDefault> Producer<T>{pub(super) fn new()->Self{Self(std::marker::PhantomData)}}
impl<T:NativeDefault> crate::retirement::RetireOwned for Producer<T>{type RetirementCursor=<() as crate::retirement::RetireOwned>::RetirementCursor;fn retirement_seed(self)->Self::RetirementCursor{crate::retirement::RetireOwned::retirement_seed(())}fn controlled_retirement_supported()->bool{<() as crate::retirement::RetireOwned>::controlled_retirement_supported()}}
pub(super) enum Operation<'turn,T:NativeDefault>{Reserve(&'turn mut NativeOwnedStorage<T::Cursor>),Seed(&'turn mut NativeOwnedStorage<T::Cursor>),Take(&'turn mut T::Cursor,&'turn mut Option<T>),Advance(&'turn mut T::Cursor,usize)}
impl<T:NativeDefault> OriginalEffectProducer for Producer<T>{type Output=RetainedCloneStep;type Failure=OriginalReceivingPrimary;type Context<'turn,'source>=Operation<'turn,T> where 'source:'turn;
 fn validate_context<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn receive<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>where 'source:'turn{match context{Operation::Take(cursor,output)=>cursor.take(output,effect,reply),Operation::Advance(cursor,body)=>cursor.advance_local(*body,effect,reply),Operation::Reserve(storage)=>Ok(match storage.reserve_empty(effect){crate::RetainedWorkPoll::Pending{..}=>reply.pending(),crate::RetainedWorkPoll::Complete(turn)=>reply.complete(turn.result.map_err(Into::into))}),Operation::Seed(storage)=>Ok(match storage.initialize_seed(effect,||Ok(T::default_cursor())){crate::RetainedWorkPoll::Pending{..}=>reply.pending(),crate::RetainedWorkPoll::Complete(turn)=>reply.complete(turn.result.map_err(Into::into))})}}
 fn recover<'reply,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>where 'source:'turn{match context{Operation::Take(cursor,output)=>cursor.recover_take(output,effect,reply),Operation::Advance(cursor,body)=>cursor.recover_advance_local(*body,effect,reply),_=>Ok(reply.pending())}}
}
